import{_ as e,o as a,c as r,a3 as d}from"./chunks/framework.BTt0kA_k.js";const o="/RelayPulse/screenshots/user/probe-advanced.webp",i="/RelayPulse/screenshots/user/model-request.webp",f=JSON.parse('{"title":"探针配置与状态判定","description":"","frontmatter":{},"headers":[],"relativePath":"user/use/probes.md","filePath":"user/use/probes.md"}'),l={name:"user/use/probes.md"};function s(n,t,p,h,c,u){return a(),r("div",null,[...t[0]||(t[0]=[d('<h1 id="探针配置与状态判定" tabindex="-1">探针配置与状态判定 <a class="header-anchor" href="#探针配置与状态判定" aria-label="Permalink to &quot;探针配置与状态判定&quot;">​</a></h1><p>入口：<strong>配置 → 站点管理 → 选择站点</strong>。连接、频率和健康阈值在“高级设置”里，请求内容在“默认探针策略”或“模型探针设置”里。</p><h2 id="设置探测频率和健康阈值" tabindex="-1">设置探测频率和健康阈值 <a class="header-anchor" href="#设置探测频率和健康阈值" aria-label="Permalink to &quot;设置探测频率和健康阈值&quot;">​</a></h2><p>点击“高级设置”，调整后点击抽屉中的“保存”。</p><table tabindex="0"><thead><tr><th>配置</th><th>新建站点默认值</th><th>可填范围</th><th>含义</th></tr></thead><tbody><tr><td>探测频率</td><td>300 秒</td><td>1–86400 秒</td><td>每个已启用模型自动探测的间隔</td></tr><tr><td>首 Token 慢阈值</td><td>5 秒</td><td>1–100 秒</td><td>流式请求首 Token 达到此值时判为偏慢</td></tr><tr><td>总耗时慢阈值</td><td>30 秒</td><td>1–500 秒</td><td>请求成功但总耗时达到此值时判为偏慢</td></tr><tr><td>连续失败转红</td><td>3 次</td><td>1–10 次</td><td>连续失败达到此次数后判为不可用</td></tr><tr><td>连续成功恢复</td><td>2 次</td><td>1–10 次</td><td>从不可用状态恢复需要的连续成功次数</td></tr></tbody></table><p>慢阈值用于判断“偏慢”，<strong>达到慢阈值不会中断请求</strong>。偏慢仍属于成功响应，参与连续成功计数。数值输入须为整数。</p><figure class="guide-figure"><p><a href="/RelayPulse/screenshots/user/probe-advanced.webp"><img src="'+o+'" alt="站点高级设置中的探测频率、首 Token 慢阈值、总耗时慢阈值和健康判定阈值"></a></p><figcaption>① 探测频率；② 健康判定阈值。本例将首 Token 慢阈值改为 1 秒以展示“偏慢”；新建站点默认值为上表中的 5 秒。</figcaption></figure><p>自动探测需要同时满足：应用在运行、通用设置“关闭主窗口后继续运行”开启、站点启用、模型启用。关闭开关会停止后续派发，已经发出的请求会正常结束并保存结果。</p><h2 id="编辑站点默认策略" tabindex="-1">编辑站点默认策略 <a class="header-anchor" href="#编辑站点默认策略" aria-label="Permalink to &quot;编辑站点默认策略&quot;">​</a></h2><ol><li>在站点详情的“默认探针策略”区域，点击“编辑默认值”。</li><li>在“请求头 Headers”和“请求体 Body”页签中编辑请求参数。</li><li>检查“请求预览”，点击“保存”。</li></ol><p>请求头和请求体使用同一套参数编辑器，支持添加字段和粘贴 JSON。勾选的参数会发送；取消勾选会保留配置但不发送。这里保存的策略供继承站点默认的模型使用。</p><h2 id="给单个模型配置请求" tabindex="-1">给单个模型配置请求 <a class="header-anchor" href="#给单个模型配置请求" aria-label="Permalink to &quot;给单个模型配置请求&quot;">​</a></h2><p>在模型行打开“模型探针设置”。</p><ul><li><strong>继承站点默认</strong>：模型没有单独保存策略时，直接使用站点默认请求头和请求体。</li><li><strong>独立策略</strong>：单独保存模型配置后，该模型使用自己的请求头和请求体；即使内容与站点默认完全相同，也属于独立策略。</li><li><strong>自定义策略</strong>：开启“自定义探针请求”后，该模型可以使用自己的探测端点、请求头和请求体。端点开关与参数配置彼此独立。</li></ul><p>自定义探针请求使用 <code>POST</code>，沿用站点协议解析响应，并继承站点凭据。端点必须与 Base URL 同源；请求头和请求体由该模型当前策略配置。它不会修改站点默认策略。</p><p>模型没有单独保存策略时才继承站点默认。保存过独立策略后，即使内容与默认完全相同，也仍是独立策略；“自定义探针请求”开关只控制探测端点是否单独配置，不会清除已保存的请求头和请求体。</p><figure class="guide-figure"><p><a href="/RelayPulse/screenshots/user/model-request.webp"><img src="'+i+'" alt="模型探针设置中的自定义探针请求开关、请求参数和请求预览入口"></a></p><figcaption>① 自定义端点；② 请求参数表；③ 请求预览与“试探一次”。向下滚动可阅读完整预览，检查后再保存。</figcaption></figure><h2 id="怎样使用请求参数表" tabindex="-1">怎样使用请求参数表 <a class="header-anchor" href="#怎样使用请求参数表" aria-label="Permalink to &quot;怎样使用请求参数表&quot;">​</a></h2><p>请求头和请求体编辑器都支持添加、删除、启停参数，以及通过“粘贴 JSON”导入已有内容。</p><ul><li>文本、数字和布尔值应选用对应类型，避免把数字作为字符串发送。</li><li>对象可添加子参数，使用对象路径组织嵌套字段；关闭父参数后，其子参数也不会发送。</li><li>JSON 类型填写合法 JSON，可用于数组或需要完整 JSON 表达的值。</li><li>绑定“当前探测模型”的字段会随执行模型替换，预览里会显示当前模型或模型占位。</li><li>导入 JSON 后先检查字段类型、模型绑定和请求预览，再保存。</li></ul><p>探测端点、请求参数和请求头按配置原文发送，不会自动补 <code>/v1</code>、斜杠或服务商专用字段。访问凭据使用站点凭据配置；通用 HTTP 头由 HTTP 客户端提供。需要其他字段时，请在请求头或请求体中明确配置，并先检查请求预览。</p><p>参数是否被接受取决于服务商和模型。默认请求优先采用短提示、较少输出 Token；推理模型若只返回思考内容或输出被截断，可按服务商要求调整输出上限和推理参数。</p><h2 id="试探一次和正式探测的区别" tabindex="-1">试探一次和正式探测的区别 <a class="header-anchor" href="#试探一次和正式探测的区别" aria-label="Permalink to &quot;试探一次和正式探测的区别&quot;">​</a></h2><p>“试探一次”出现在模型的自定义请求配置中，使用当前草稿发送真实请求。它不会自动保存草稿，不写入正式探测历史，也不推进模型健康状态。</p><p>确认草稿试探成功后，点击“保存”，再通过模型行“立即探测模型”或“探测已启用模型”发起正式探测。正式探测会写入历史并更新健康状态。</p><h2 id="健康状态怎样判定" tabindex="-1">健康状态怎样判定 <a class="header-anchor" href="#健康状态怎样判定" aria-label="Permalink to &quot;健康状态怎样判定&quot;">​</a></h2><table tabindex="0"><thead><tr><th>状态</th><th>含义</th></tr></thead><tbody><tr><td>等待探测</td><td>当前尚无可展示的正式探测结果</td></tr><tr><td>待确认</td><td>已有结果，尚未达到稳定健康判定的阈值</td></tr><tr><td>正常</td><td>已建立稳定健康状态，成功请求未达到慢阈值</td></tr><tr><td>偏慢</td><td>成功请求的首 Token 或总耗时达到慢阈值</td></tr><tr><td>不可用</td><td>连续失败达到“连续失败转红”阈值</td></tr></tbody></table><p>已有稳定状态时，少量失败在达到阈值前会保持上一次稳定状态。红灯后需要达到连续成功恢复次数才会恢复；偏慢结果也计为成功。</p><p>尚无稳定状态时，默认阈值下连续失败未满 3 次会显示“待确认”；首次成功即可转为正常或偏慢。模型已经转红后，才需要连续成功 2 次恢复。一次失败会立即出现在探测记录里，但不一定立即让小面板转红。</p><h2 id="成功与耗时的口径" tabindex="-1">成功与耗时的口径 <a class="header-anchor" href="#成功与耗时的口径" aria-label="Permalink to &quot;成功与耗时的口径&quot;">​</a></h2><p>常规模型请求需要成功 HTTP 响应、有效回答正文，以及协议要求的完成标记。只有连接成功、HTTP 200 或思考内容，不能单独证明模型探测成功。</p><p>自定义 HTTP 请求按 2xx 状态和响应体完整读取判断，不要求模型回答格式。</p><p>流式首 Token 从请求开始计时，到第一段非空思考或回答文本到达为止；空增量、角色信息、心跳和工具参数不触发首 Token 计时。非流式和自定义 HTTP 请求的首 Token 显示为 <code>—</code>。</p>',33)])])}const T=e(l,[["render",s]]);export{f as __pageData,T as default};
